base:
import { lire } from "./io";

export function total(items) {
  let s = 0;
  for (const i of items) {
    s += i.prix;
  }
  return s;
}

export function moyenne(items) {
  if (!items.length) return 0;
  return total(items) / items.length;
}

export const TVA = 0.2;

